out=[]; A=out.append
def h2(x): A('<h2>'+x+'</h2>')
def h3(x): A('<h3>'+x+'</h3>')
def p(x):
    for piece in x.split('@@'): A('<p>'+piece.strip()+'</p>')
def ul(items, o=False):
    t='ol' if o else 'ul'
    A('<'+t+'>')
    for i in items: A('<li>'+i+'</li>')
    A('</'+t+'>')
def tbl(heads, rows):
    A('<div class="table-responsive"><table><tbody><tr>'+''.join('<th>'+h+'</th>' for h in heads)+'</tr>')
    for r in rows: A('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>')
    A('</tbody></table></div>')

